insert into storage.buckets(id,name,public) values('product-images','product-images',true),('branding','branding',true) on conflict do nothing;alter table storage.objects enable row level security;create policy "public read catalogue assets" on storage.objects for select using(bucket_id in ('product-images','branding'));create policy "super admin manages assets" on storage.objects for all using(public.has_role('super_admin')) with check(public.has_role('super_admin'));